from pathlib import Path
import json,html
p=Path(__file__).resolve().parents[1]
icons=json.loads(Path(__file__).with_name('icons.json').read_text())
items=json.loads((p/'assets/workflows.json').read_text())['items']
I=lambda n:icons[n]
E=lambda s:html.escape(str(s),quote=True)
def icon(n,cls=''):return '<span class="icon '+cls+'">'+I(n)+'</span>'
def wire(paths,view='0 0 1000 520'):
 return '<svg class="wires" viewBox="'+view+'" aria-hidden="true">'+''.join('<path d="'+d+'"/>' for d in paths)+'</svg>'
def node(name,sub,x,y,ico='Workflow',cls='',key=''):
 return f'<div class="flow-node {cls}" data-step="{key}" style="--x:{x}%;--y:{y}%">{icon(ico)}<b>{name}</b><small>{sub}</small><span class="port left"></span><span class="port right"></span></div>'
def canvas(compact=False):
 return '''<div class="n8n-window"><header><span class="n8n-name">n8n</span><span>OCD / Renewal follow-up</span><strong>PROPOSED WORKFLOW</strong></header><div class="canvas-toolbar"><span>Renewal check</span><span>Illustration · not connected</span></div><div class="node-canvas"><svg class="wires workflow-wires" aria-hidden="true"><path data-from="trigger" data-to="source"/><path data-from="source" data-to="rule"/><path data-from="rule" data-to="draft"/><path data-from="draft" data-to="review" class="human-wire"/><path data-from="rule" data-to="skip" class="skip-wire"/></svg>'''+node('Schedule Trigger','Daily · agreed timezone',2,32,'CalendarClock',key='trigger')+node('HTTP Request','Approved register API',24,32,'Database',key='source')+node('IF','Expiry within 30 days?',46,32,'Settings',key='rule')+node('Microsoft Outlook','Create a draft',68,32,'Mail',key='draft')+node('Office review','Outside n8n · verify & send',68,76,'UserRoundCheck','human',key='review')+node('No reminder','Valid beyond threshold',24,76,'FileCheck',key='skip')+'''<span class="branch-label yes">TRUE</span><span class="branch-label no">FALSE</span><div class="canvas-key"><span></span> Proposed automation <span class="key-human"></span> Office action</div></div><footer><span>Illustrative 30-day rule · confirm policy and source access</span><span>No live accounts connected</span></footer></div>'''
def laptop(inner):return '<div class="laptop"><div class="laptop-screen"><span class="camera"></span>'+inner+'</div><div class="laptop-base"></div></div>'
slides=[]
def add(label,title,body,cls='',note='Proposed design · not a live automation'):
 n=len(slides)+1
 slides.append(f'<section class="slide {cls}" id="slide-{n}" data-title="{E(label)}" aria-labelledby="h-{n}"><div class="slide-top"><span>{E(label)}</span><span>OCD BRILLIANCE × HIVE CX</span></div><h1 id="h-{n}">{title}</h1><div class="slide-content">{body}</div><footer class="slide-foot"><span>{note}</span><span>{n:02} / TOTAL</span></footer></section>')
add('The automation proposal','n8n<br>for OCD.',laptop(canvas(True))+'''<div class="cover-caption"><span>35 WORKFLOWS · FIVE PILOT PRIORITIES</span><p>The work, connected.</p></div>''','cover',note='Prepared for Adriana & Felician · 30 October 2026')
add('01 / Where n8n fits','Connect the work.<br>Keep the systems.',
'''<div class="systems-visual">'''+wire(['M170 95 H375 Q420 95 420 145 V240 H480','M170 240 H480','M170 390 H375 Q420 390 420 335 V240 H480','M570 240 H700 Q740 240 740 110 H860','M570 240 H860','M570 240 H700 Q740 240 740 380 H860'])+f'''<div class="system source s1">{icon('Mail')}<b>Outlook</b><small>Email & forms</small></div><div class="system source s2">{icon('Phone')}<b>Dialpad / VA</b><small>Staff-logged initially</small></div><div class="system source s3">{icon('FileText')}<b>Approved exports</b><small>Source evidence</small></div><div class="n8n-hub"><b>n8n</b><span>CHECK · PREPARE<br>COORDINATE</span></div><div class="system target t1">{icon('Users')}<b>ShiftCare</b><small>API / handoff to validate</small></div><div class="system target t2">{icon('Receipt')}<b>Xero</b><small>Supported invoices / contacts</small></div><div class="system target t3">{icon('UserRoundCheck')}<b>Your team</b><small>Decisions & release</small></div></div><div class="visual-caption">n8n coordinates steps. Staff retain care, staffing and financial decisions.</div>''','systems-slide',note='Outlook / Xero nodes documented · ShiftCare API access, permitted operations and account permissions need validation')
add('01 / A visual workflow','A renewal, followed through.','''<div class="demo-controls"><label for="sample-record">SAMPLE RECORD</label><select id="sample-record"><option value="due">Renewal due in 14 days</option><option value="valid">Valid for 120 days</option><option value="missing">Expiry date missing</option></select><button id="walkthrough" type="button">Run sample</button><span>Fictional data · no messages sent</span></div><div class="workflow-viewport" tabindex="0" aria-label="Proposed n8n workflow; scroll horizontally on a small screen">'''+canvas()+'''</div><div class="workflow-result" role="status" aria-live="polite" aria-atomic="true"><div><span id="result-step">READY TO WALK THROUGH</span><b id="result-title">Follow one renewal.</b></div><p id="result-copy">Choose a sample and run each step. See what n8n prepares and where the office takes over.</p><span id="result-outcome">Sample only</span></div>''','canvas-slide',note='Proposed configuration · missing or invalid expiry requires office review; creating a draft does not send it')
add('The problem / the proposed response','Less chasing. Visible ownership.',
'''<div class="comparison"><div class="manual-scene"><span class="scene-label">MANUAL TODAY</span>'''+''.join(f'<div class="paper paper-{j}">{icon(ico)}<span>{txt}</span><i></i><i></i></div>' for j,(ico,txt) in enumerate([('Mail','Another email'),('FileText','Missing file'),('CalendarClock','Follow up'),('Phone','A missed reply')]))+f'''<div class="manual-person">{icon('UserRound')}<span>Remember · search · repeat</span></div></div><div class="owned-scene"><span class="scene-label">PROPOSED WITH n8n</span><div class="case-board"><header>{icon('Workflow')}<b>One owned case</b></header><div>{icon('Mail')}<span>Source linked</span><b>1</b></div><div>{icon('UserRoundCheck')}<span>Office owner</span>{icon('Check')}</div><div>{icon('Clock')}<span>Follow-up date</span>{icon('Check')}</div><div>{icon('ShieldCheck')}<span>Result checked</span>{icon('Check')}</div></div><p>Nothing closes without a checked outcome.</p></div></div>''','comparison-slide',note='Illustrative process model · actual savings are measured in the pilot')
pilot=[(3,'Enquiry ownership','Mail','Time'),(19,'Document check','FileCheck','Compliance'),(21,'Renewal follow-up','CalendarClock','Compliance'),(22,'Invoice checks','Receipt','Cashflow'),(28,'Hours & mileage','Timer','Time / payroll')]
add('02 / Recommended Phase 1','Five workflows to prove first.',
'''<div class="pilot-visual">'''+''.join(f'<a href="register.html#workflow-{n}" class="pilot-pod"><span class="pod-number">ITEM {n:02}</span><div class="pod-art">{icon(ico)}<span class="orbit-dot"></span></div><h2>{txt}</h2><small>{tag}</small></a>' for n,txt,ico,tag in pilot)+'''</div><div class="pilot-flow"><span>Approved sources</span><i></i><span>Build & test</span><i></i><span>Staff review</span><i></i><span>Measure the pilot</span></div>''','pilot-slide',note='One team, one set of approved rules · source collection and filing routes are foundation work')
group_names=['Enquiries','People & messages','Bookings','Cover & documents','Renewals & billing','Payments & payroll','Care & follow-through']
shortnames=['Area screening','Collect enquiries','Enquiry owner','Missing details','Participant profile','Worker onboarding','Client stages','Draft messages','Message history','Booking checks','Change scope','Travel checks','Instructions','Confirmations','Cancellations','Replacement cover','Absence history','File matching','Missing documents','Date corrections','Renewals','Invoice checks','Special billing','Billing recipient','Returned invoices','Payment follow-up','Pay period checks','Hours & mileage','Pay adjustments','Payroll handoff','Visit exceptions','Care follow-up','Task handovers','Outcome reporting','Arrival visibility']
itemicons=['MapPin','Mail','UserRoundCheck','Search','Users','Users','Settings','MessageSquare','Files','CalendarClock','CalendarClock','MapPin','FileText','Check','X','Users','CalendarClock','Files','FileCheck','CalendarClock','Bell','Receipt','CircleDollarSign','UserRound','Receipt','CircleDollarSign','CalendarClock','Timer','Settings','ClipboardCheck','FileCheck','ShieldCheck','ClipboardCheck','Workflow','MapPin']
tabs=''.join(f'<button type="button" role="tab" id="group-tab-{g}" aria-controls="group-{g}" aria-selected="{str(g==0).lower()}" tabindex="{0 if g==0 else -1}" data-group="{g}">{name}</button>' for g,name in enumerate(group_names))
groups=''
for g in range(7):
 cards=''
 for j,i in enumerate(items[g*5:g*5+5]):
  n=i['number'];cards+=f'<a class="process-tile" href="register.html#workflow-{n}" data-item="{n}"><span>{n:02}</span>{icon(itemicons[n-1])}<b>{E(shortnames[n-1])}</b><small>{E(i["phase"])}</small></a>'
 groups+=f'<div class="group-panel" role="tabpanel" id="group-{g}" aria-labelledby="group-tab-{g}"{ " hidden" if g else ""}>{cards}</div>'
add('01 / All 35 items','Every item. A defined response.',f'''<div class="register-screen"><header><b>OCD workflow map</b><span>SELECT AN AREA, THEN AN ITEM</span></header><div class="map-tabs" role="tablist" aria-label="Workflow areas">{tabs}</div>{groups}<div class="map-legend"><span><b>05</b> Pilot</span><span><b>15</b> Remaining core</span><span><b>05</b> Conditional</span><span><b>10</b> Later / native</span></div></div>''','map-slide',note='The 35 opportunities trace to the broader 96-point pain register · select an item for tools, human steps and acceptance')
phases=[('Foundation','1–2 weeks',20,32,0,14,'Access + rules'),('Five-item pilot','4–6 weeks',70,110,14,43,'Test + train'),('15 remaining core','4–6 weeks',90,150,43,73,'Pilot gate'),('5 conditional','3–5 weeks',60,100,73,94,'Item gates'),('Later / native','Scope separately',12,20,94,100,'Scoping only')]
bars=''.join(f'<div class="gantt-row"><div><b>{name}</b><span>{duration}</span></div><div class="gantt-track"><span class="gantt-bar bar-{j}" style="--start:{start}%;--end:{end}%;"><small>{tag}</small></span></div><strong>AUD {lo*75:,}–{hi*75:,}</strong></div>' for j,(name,duration,lo,hi,start,end,tag) in enumerate(phases))
add('03 / Delivery phases','Build in phases. Release on evidence.',f'''<div class="timeline"><div class="timeline-head"><span>DELIVERY STAGE</span><div><span>Foundation</span><span>Pilot</span><span>Expansion</span></div><span>ILLUSTRATIVE COST</span></div>{bars}</div><div class="quote-assumption"><b>AUD 75 / hour</b><span>Planning assumption, not a supplier quote. Tax, hosting and subscriptions excluded.</span></div>''','timeline-slide',note='New planning ranges · timing starts when access and decisions are ready; later-item implementation is not priced')
add('03 / First approval envelope','Foundation + five-workflow pilot.',
'''<div class="budget-visual"><div class="effort-foundation"><svg viewBox="0 0 200 200" aria-hidden="true"><circle cx="100" cy="100" r="82"/></svg><span>FOUNDATION</span><b>20–32 h</b><small>AUD 1,500–2,400</small></div><span class="budget-plus">+</span><div class="effort-pilot"><svg viewBox="0 0 240 240" aria-hidden="true"><circle cx="120" cy="120" r="104"/></svg><span>PILOT BUILD</span><b>70–110 h</b><small>AUD 5,250–8,250</small></div><div class="budget-total"><span>ILLUSTRATIVE ENVELOPE</span><strong>AUD 6,750<br>–10,650</strong><p>5–8 weeks delivery<br>+ 2-week observation window</p></div></div>''','budget-slide',note='90–142 hours × illustrative AUD 75/hour · confirm supplier rate, scope and fixed quote before authorizing')
add('04 / How we will measure success','A pilot scorecard. Not a promise.',
'''<div class="metrics-visual"><article><div class="gauge"><svg viewBox="0 0 200 130"><path class="gauge-bg" d="M25 110 A75 75 0 0 1 175 110"/><path class="gauge-value partial" d="M25 110 A75 75 0 0 1 175 110"/></svg><strong>−25%</strong></div><h2>Admin time / case</h2><span>Proposed target</span></article><article><div class="zero-scene">'''+icon('Mail')+'''<strong>0</strong></div><h2>Unowned overdue cases</h2><span>Proposed target</span></article><article><div class="ring-gauge"><svg viewBox="0 0 160 160"><circle class="ring-bg" cx="80" cy="80" r="62"/><circle class="ring-value" cx="80" cy="80" r="62"/></svg><strong>100%</strong></div><h2>Known exceptions caught</h2><span>Agreed test set only</span></article></div><div class="measure-sequence"><div><b>01</b><span>2-week baseline</span></div><i></i><div><b>02</b><span>Pilot + observation</span></div><i></i><div><b>03</b><span>Compare net time & returns</span></div></div>''','metrics-slide',note='Also track invoice rejection and median days to payment · no measured savings or faster-payment guarantee yet')
add('05 / Ownership after launch','An owner. A maintainer. A backup.',
'''<div class="maintenance-visual">'''+wire(['M230 240 H430','M570 240 H770','M840 320 V425 H160 V320'])+f'''<div class="owner-role r1">{icon('Building2')}<b>OCD process owner</b><span>Rules & sign-off</span></div><div class="owner-role r2">{icon('Settings')}<b>n8n maintainer</b><span>Failures · updates · restore</span></div><div class="owner-role r3">{icon('Users')}<b>Office + backup</b><span>Exceptions & fallback</span></div><div class="maintenance-cycle">{icon('RefreshCw')}<span>DAILY QUEUE</span><span>WEEKLY CHECKS</span><span>MONTHLY RESTORE TEST</span></div></div><div class="support-allowance"><b>4–8 hours / month</b><span>Illustrative AUD 300–600 + infrastructure.<br>Named maintainer, backup and response hours to be contracted.</span></div>''','maintenance-slide',note='Proposed: designated Hive CX maintainer · OCD controls accounts, workflow exports and recovery access')
add('06 / Data and offshore access','Australian records.<br>Controlled access.',
'''<div class="access-visual"><div class="au-zone"><span class="zone-label">PROPOSED AUSTRALIAN HOSTING</span><div class="server-rack">'''+icon('Server')+'''<b>n8n + database</b><span>Protected secrets · minimized logs</span></div><div class="source-records"><span>ShiftCare</span><span>Xero</span><span>Approved mailbox</span></div></div><div class="access-gate">'''+icon('LockKeyhole')+'''<b>ACCESS GATE</b><span>Named account<br>MFA · least privilege<br>Logged activity</span></div><div class="ph-zone"><span class="zone-label">PHILIPPINE-BASED SUPPORT</span>'''+icon('Laptop')+'''<b>Managed device</b><span>Only authorized tasks<br>Restricted downloads<br>Prompt access removal</span></div></div><div class="privacy-gate">APP 8 assessment + supplier terms + participant notices / consent + incident plan <b>before access</b></div>''','access-slide',note='Australian hosting alone does not settle cross-border obligations · OAIC APP 8 / APP 11 and NDIS information management')
add('The next decision','Approve a defined first step.',
'''<div class="approval-visual">'''+''.join(f'<div class="approval-gate">{icon(ico)}<span>GATE {j+1:02}</span><h2>{txt}</h2><div class="unsigned">To agree</div></div>' for j,(ico,txt) in enumerate([('ClipboardCheck','Five pilot workflows'),('CircleDollarSign','Quote & delivery window'),('LockKeyhole','Owners & data access')]))+'''</div><div class="closing-downloads"><a href="register.html">Explore all 35 items</a><a href="assets/workflow-register.csv" download>Download item register</a><a href="assets/ocd-automation-proposal.pdf" download>Download slides as PDF</a></div>''','approval-slide',note='Proposal for discussion · nothing here authorizes live automation, expenditure or offshore access')
add('Evidence / source notes','The detail stays available.',
'''<div class="evidence-visual"><a class="document-preview" href="register.html">'''+icon('Files')+'''<b>35-item<br>working register</b><span>Tools · staff steps · gates · evidence</span></a><div class="source-links"><a href="https://docs.n8n.io/integrations/builtin/app-nodes/n8n-nodes-base.microsoftoutlook/">n8n: Outlook</a><a href="https://docs.n8n.io/integrations/builtin/app-nodes/n8n-nodes-base.xero/">n8n: Xero node</a><a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.httprequest/">n8n: HTTP Request</a><a href="https://www.oaic.gov.au/privacy/australian-privacy-principles/australian-privacy-principles-guidelines/chapter-8-app-8-cross-border-disclosure-of-personal-information">OAIC: cross-border disclosure</a><a href="https://www.oaic.gov.au/privacy/australian-privacy-principles/australian-privacy-principles-guidelines/chapter-11-app-11-security-of-personal-information">OAIC: security of information</a><a href="https://www.ndiscommission.gov.au/rules-and-standards/ndis-practice-standards/core-module-provider-governance-and-operational">NDIS: information management</a></div></div>''','evidence-slide',note='Project: 24 Oct opportunities / 25 Oct feasibility / 23 Oct pain register · six questions from the supplied client message')
count=len(slides)
menu=''.join(f'<a href="#slide-{n}"><span>{n:02}</span>{E(s.split("data-title=\"")[1].split("\"")[0])}</a>' for n,s in enumerate(slides,1))
doc='''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A visual n8n automation proposal for OCD Brilliance, answering Felician’s six questions and mapping all 35 workflows."><title>OCD Brilliance · n8n visual automation proposal</title><meta name="theme-color" content="#292929"><link rel="icon" href="prototype/assets/ocd-brilliance-logo.png"><link rel="stylesheet" href="assets/visual-deck.css"><script src="assets/deck.js" defer></script><script src="assets/visual-deck.js" defer></script></head><body><a class="skip" href="#deck">Skip to slides</a><header class="deck-header"><a href="#slide-1">OCD <b>BRILLIANCE</b><span> × HIVE CX</span></a><nav aria-label="Presentation tools"><a href="register.html">35-item register</a><button id="overview" aria-expanded="false" aria-controls="slide-menu">Slides</button><button id="print">Print / PDF</button><button id="fullscreen">Full screen</button></nav></header><div id="slide-menu" hidden><nav aria-label="All slides">MENU</nav></div><main id="deck" tabindex="-1">BODY</main><footer class="deck-controls"><span class="controls-hint">Keyboard: left / right</span><div><button id="prev" aria-label="Previous slide">Previous</button><span id="counter" aria-live="polite">01 / COUNT</span><button id="next" aria-label="Next slide">Next</button></div><span id="chapter-label">The automation proposal</span></footer><div class="deck-progress" aria-hidden="true"><span></span></div><dialog id="workflow-dialog"><button class="dialog-close" aria-label="Close workflow detail">Close</button><div id="dialog-body"></div></dialog><script type="application/json" id="workflow-data">DATA</script><noscript><p class="no-script">All slides appear below without JavaScript. Open the working register for every item.</p></noscript></body></html>'''
doc=doc.replace('MENU',menu).replace('BODY',''.join(slides)).replace('TOTAL',str(count)).replace('COUNT',str(count)).replace('DATA',json.dumps(items).replace('<','\\u003c'))
# Publish the new markup only once its CSS and behavior assets exist.
for name in ['visual-deck.css','visual-deck.js']:assert (p/'assets'/name).exists(),name
(p/'index.next.html').write_text(doc);(p/'index.next.html').replace(p/'index.html')
print('Built',count,'visual slides with n8n canvas and all 35 interactive items')
